// The kit's stylesheet is a hand-written file at the package root, not something the
// bundler produces - so it resolves the same before a build, after one, and from a
// published tarball. That matters more than it sounds: Tailwind resolves CSS imports with
// its own resolver, which knows nothing about the `@pg/source` condition the rest of the
// repo relies on, and would otherwise look for a `dist` that may not exist yet.
//
// The exports map is regenerated by tsdown from the JavaScript entry points, so this runs
// afterwards and puts back the one entry tsdown has no way to know about.

import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const manifestPath = fileURLToPath(new URL('../packages/ui/package.json', import.meta.url))
const manifest = JSON.parse(await readFile(manifestPath, 'utf8'))

const withStyles = (exports) => {
  const next = {}
  for (const [specifier, value] of Object.entries(exports)) {
    // Kept before `./package.json`, which conventionally goes last.
    if (specifier === './package.json') next['./styles.css'] = './styles.css'
    next[specifier] = value
  }
  return next
}

manifest.exports = withStyles(manifest.exports)
if (manifest.publishConfig?.exports) {
  manifest.publishConfig.exports = withStyles(manifest.publishConfig.exports)
}

await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)

console.log('@pg/ui: styles.css kept in the exports map')
